"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The drowned choir', 'author': 'Signature original', 'genre': 'Folk Horror', 'chapters': [{'n': 1, 'title': 'Move-In', 'text': "Ben Marsh got the keys to the marsh village on a Tuesday, in fog so thick the house was a rumor until the door opened. It smelled of dust and old winters. It felt — Ben Marsh would later swear — like being watched by something patient.\n\nher colleague Priya helped carry boxes and didn't stay for dinner. 'Call me,' her colleague Priya said, 'if the walls start talking.' It was a joke. Ben Marsh laughed. The house didn't.\n\nThe first night, Ben Marsh found a music box that plays itself. It wasn't in any box. It was waiting — on the mantel, in the nursery, at the foot of the bed, depending on which telling you believe. This telling says: the mantel."}, {'n': 2, 'title': 'Escalation', 'text': "'the drowned choir,' her colleague Priya whispered, though Ben Marsh hadn't said the name yet. Everyone in the county knew the story of the marsh village. Everyone pretended they didn't.\n\nBen Marsh researched. The archives gave up their dead reluctantly: a death in the marsh village, then another, then the silence that means everyone agreed not to speak. a music box that plays itself appeared in every account, patient as a spider.\n\nDay three: a music box that plays itself moved on its own. Day four: the whispers started in the walls, spelling a name Ben Marsh almost recognized. Day five: her colleague Priya came for dinner and went white at the cold spot on the stairs."}, {'n': 3, 'title': 'The Pattern', 'text': "The nursery door, locked for decades, opened for Ben Marsh like it had been waiting. Inside: dust, a small bed, and a music box that plays itself's twin — the other half of whatever had been broken that terrible night.\n\nBen Marsh mapped it like a disease: every incident in the marsh village centered on a music box that plays itself, and every a music box that plays itself led back to the same date, the same room, the same name. the drowned choir wasn't haunting the house. the drowned choir was the house, wearing it like a coat.\n\nher colleague Priya brought salt, iron, sage — the whole apotropaic grocery list. Ben Marsh brought a camera, a recorder, and the stubbornness that had gotten them this far. 'We document,' Ben Marsh said. 'Then we end it.'"}, {'n': 4, 'title': 'The Night', 'text': 'The scream, when it came, was relief. The cold spot warmed. The whispers stopped mid-word. Ben Marsh and her colleague Priya stood in the sudden ordinary silence of the marsh village, holding a music box that plays itself, whole at last, and wept like children.\n\nher colleague Priya arrived — of course her colleague Priya did, called by the thing friends are — with headlights and a crowbar and no plan at all. Together they forced the drowned choir back toward the nursery, toward a music box that plays itself, toward the broken place.\n\nBen Marsh understood then what had to be done: not destroy a music box that plays itself, but complete it. Join the halves. Speak the name. Give the drowned choir what it had wanted all along — to be seen, to be mourned, to be released.'}, {'n': 5, 'title': 'Aftermath', 'text': "a music box that plays itself, mended, sits on the mantel. It doesn't play, or fill, or show. It's just an object now — which is to say, it's just a story. Ben Marsh keeps it to remember: some doors stay shut.\n\nThe archives got a new entry, in Ben Marsh's handwriting: what happened, what worked, what it cost. Let the next tenant know. Let no one ever pretend again.\n\nthe marsh village is for sale again, and Ben Marsh is staying. Someone has to be here who knows. Someone has to keep the light on. That someone is Ben Marsh now."}, {'n': 6, 'title': 'Epilogue: The Light Kept', 'text': "her colleague Priya visits every anniversary with pancakes and bad jokes. They don't talk about that night. They don't need to. It's in the walls — but the walls, now, are just walls.\n\nsome doors stay shut — Ben Marsh wrote it on the first page of the archive, and on the last. Whoever comes next will read it. Whoever comes next will know.\n\nYears later, Ben Marsh still walks the marsh village at night, checking the rooms the way you check on sleeping children. The nursery is a study now. The cold spot is just a draft. Mostly."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

